  profileCharts.push(new Chart(document.querySelector('#career-chart'), { type:'doughnut', data:{labels:[t('wins'),t('losses')],datasets:[{data:[won,lost],backgroundColor:['#d6a516','#5e5b55'],borderWidth:0}]},options:{plugins:{legend:{labels:{color:'#f6f0e2'}}},cutout:'68%'} })); const rankMonths = [...new Set(dates.map(date => date.slice(0,7)))], category = player.schoolLevel || '', ranks = rankMonths.map(month => { const records = new Map(); data.matches.filter(match => eventType(match) === 'Training' && isComplete(match) && match.matchDate.startsWith(month)).forEach(match => [[match.player1Id,match.winnerId === match.player1Id],[match.player2Id,match.winnerId === match.player2Id]].forEach(([id,won]) => { if ((playerMap().get(id)?.schoolLevel || '') !== category) return; const record = records.get(id) || { id,wins:0,games:0 }; record.games++; if (won) record.wins++; records.set(id,record); })); const ranked = [...records.values()].sort((left,right) => right.wins / right.games - left.wins / left.games || right.games - left.games || right.wins - left.wins); return ranked.findIndex(record => record.id === playerId) + 1 || null; }), rankedMonths = ranks.filter(Boolean), maxRank = Math.max(1,...rankedMonths), latestRank = rankedMonths.at(-1) || '-', bestRank = rankedMonths.length ? Math.min(...rankedMonths) : '-', rankScores = ranks.map(rank => rank ? maxRank - rank + 1 : null); document.querySelector('#rank-summary').innerHTML = `<span><b>${latestRank}</b>${language === 'en' ? 'Latest rank' : '最新順位'}</span><span><b>${bestRank}</b>${language === 'en' ? 'Best rank' : '最高順位'}</span><span><b>${rankedMonths.length}</b>${language === 'en' ? 'Months ranked' : '順位対象月'}</span>`; profileCharts.push(new Chart(document.querySelector('#rank-chart'), { type:'bar', data:{labels:rankMonths,datasets:[{label:t('rank'),data:rankScores,displayValues:ranks.map(rank => rank ? `#${rank}` : ''),backgroundColor:ranks.map(rank => rank === 1 ? '#d6a516' : 'rgba(84,184,209,.62)'),borderRadius:5}]},options:{indexAxis:'y',scales:{x:{min:0,max:maxRank,ticks:{display:false},grid:{display:false}},y:{ticks:{color:'#f6f0e2'},grid:{display:false}}},plugins:{legend:{display:false}}} }));
  renderLatestMatchDay(completed, dates); renderPerformanceSnapshot(completed, dates); renderRankMonthList(dates); renderWinRateTrends(completed, dates); renderPeriodStats(completed, dates);
  const months = [...new Set(dates.map(date => date.slice(0,7)))].reverse(), years = [...new Set(dates.map(date => date.slice(0,4)))].reverse(); monthlyIndex = Math.min(monthlyIndex, Math.max(0,months.length-1)); yearlyIndex = Math.min(yearlyIndex, Math.max(0,years.length-1)); const block = (label, period, type, index, count) => { const rows = opponentRows(period), order = language === 'en' ? 'W/L dots: Oldest → Newest' : '勝敗ドット: 古い順 → 新しい順'; return `<article><h3>${label}: ${period}<span class="opponent-nav"><button data-period="${type}" data-direction="1" ${index >= count - 1 ? 'disabled' : ''}>‹</button><button data-period="${type}" data-direction="-1" ${index === 0 ? 'disabled' : ''}>›</button></span></h3><small class="matchup-order">${order}</small><div class="opponent-columns"><section><h4>${t('played')}</h4><ul>${opponentList(rows,'played')}</ul></section><section><h4>${t('beat')}</h4><ul>${opponentList(rows,'won')}</ul></section><section><h4>${t('lost')}</h4><ul>${opponentList(rows,'lost')}</ul></section></div></article>`; }; document.querySelector('#opponent-stats').innerHTML = block(t('monthly'),months[monthlyIndex] || '', 'month', monthlyIndex, months.length) + block(t('yearly'),years[yearlyIndex] || '', 'year', yearlyIndex, years.length);
  const archiveDates = [...new Set(matches.map(match => match.matchDate))].sort(); document.querySelector('#profile-matches').innerHTML = [...archiveDates].reverse().map(date => { const day = matches.filter(match => match.matchDate === date), completeDay = day.filter(isComplete), dayWins = completeDay.filter(match => match.winnerId === playerId).length, dayLosses = completeDay.filter(match => match.winnerId && match.winnerId !== playerId).length, decided = dayWins + dayLosses; return `<section class="match-date-group"><header><strong>${dateLabel(date)}</strong><span>${recordText(dayWins, dayLosses, day.length)} · ${decided ? Math.round(dayWins / decided * 100) : 0}%</span></header><div class="match-list">${day.map(match => { const opponent = playerMap().get(match.player1Id === playerId ? match.player2Id : match.player1Id) || { displayName: match.player1Id === playerId ? match.player2Name : match.player1Name }, score = match.player1Id === playerId ? `${match.player1Sets} - ${match.player2Sets}` : `${match.player2Sets} - ${match.player1Sets}`, result = !isComplete(match) ? 'incomplete' : match.winnerId === playerId ? 'win' : 'loss', playerDot = result === 'incomplete' ? '' : `<i class="game-result-dot ${result}" title="${t(result)}">${result === 'win' ? 'W' : 'L'}</i>`, opponentResult = result === 'win' ? 'loss' : 'win', opponentDot = result === 'incomplete' ? '' : `<i class="game-result-dot ${opponentResult}" title="${t(opponentResult)}">${opponentResult === 'win' ? 'W' : 'L'}</i>`; return `<button class="match-card player-session-card result-${result}" data-match-id="${match.matchId}"><div class="match-meta"><span>${dateLabel(match.matchDate)}</span><span class="badge training">${t('training')}</span></div><div class="match-score"><span class="match-player ${result === 'win' ? 'winner' : result === 'loss' ? 'loser' : ''}">${playerDot}${nameFor(player)}${player.schoolLevel ? `<small class="match-category">${player.schoolLevel}</small>` : ''}</span><strong class="score">${score}</strong><span class="match-player ${result === 'loss' ? 'winner' : result === 'win' ? 'loser' : ''}">${opponentDot}${nameFor(opponent)}${opponent.schoolLevel ? `<small class="match-category">${opponent.schoolLevel}</small>` : ''}</span></div><div class="match-context"><span>${match.event || (language === 'en' ? 'Little Kings Club Matches' : 'リトルキングス練習試合')}</span><b>${result === 'incomplete' ? t('incomplete') : ''}</b></div></button>`; }).join('')}</div></section>`; }).join('');
