const howToRead = { profile:{en:['How to Read This Profile','Use the all-time, latest-year, and latest-month records together. A single recent result is less meaningful than a trend across several training days. Playing style and equipment describe the player; they are not instructions to change equipment.'],ja:['選手プロフィールの見方','通算・直近年・直近月の記録を合わせて確認してください。直近1試合だけでなく、複数の練習日にわたる傾向を見ることが大切です。戦型や用具は選手を理解するための情報であり、用具変更を勧めるものではありません。']},trends:{en:['How to Read Performance Trends','Bars show wins and losses on each match day; the lines show that day’s net W-L and the cumulative trend. Look for repeated patterns over time, then use the match archive to review the scores and opponents behind them.'],ja:['成績推移の見方','棒は各試合日の勝敗、線はその日の勝敗差と累積傾向を示します。繰り返し出る傾向を確認し、試合アーカイブでその背景にあるスコアや対戦相手を振り返ってください。']},statistics:{en:['How to Read Match Statistics','Compare matches, W/L, win rate, set difference, and opponent-category records together. Win rate alone is not enough: match volume and opponent mix affect the result. Use month-to-month changes to choose one next practice target.'],ja:['試合スタッツの見方','試合数、勝敗、勝率、セット差、対戦相手カテゴリ別の記録を合わせて確認します。勝率だけでは不十分で、試合数や対戦相手の構成も結果に影響します。月ごとの変化から次の練習テーマを1つ選んでください。']},opponents:{en:['How to Read Opponent Insight','This section groups opponents by most played, most wins, and most losses. The W/L dots run oldest to newest. Repeated losses do not label a weakness by themselves; use Head to Head to inspect score lines, recent form, and tactical patterns against that opponent.'],ja:['対戦相手分析の見方','対戦数、勝利数、敗戦数が多い相手を示し、勝敗ドットは古い順から新しい順です。繰り返す敗戦だけで苦手と決めず、直接対決でスコア、直近の流れ、相手ごとの戦術パターンを確認してください。']},archive:{en:['How to Read the Match Archive','Each date groups that training day’s matches. Read the score and opponent with the W/L result: a 3-2 match offers different feedback from a 3-0 match. Click any match result to open Head to Head and review the complete matchup history.'],ja:['試合アーカイブの見方','日付ごとにその日の練習試合をまとめています。勝敗だけでなく、スコアと対戦相手を確認してください。3-2と3-0では振り返る内容が異なります。試合結果をクリックすると直接対決が開き、対戦履歴全体を確認できます。']},h2h:{en:['How to Read Head to Head','Head to Head compares only these two players. Check total matches, win rate, current streak, best streak, and the timeline together. Review close scores and recent changes first, then identify one tactical question for the next meeting, such as serve patterns, receive choices, or rally placement.'],ja:['直接対決の見方','直接対決はこの2選手だけを比較します。対戦数、勝率、現在の連勝、最多連勝、履歴を合わせて確認してください。まず接戦のスコアと直近の変化を見て、次回に向けてサーブの組み立て、レシーブの選択、ラリーのコースなど1つの戦術課題を決めます。']}};
howToRead.competitiveness = { en:['How to Read Match Competitiveness','Each row is normalized to this player: 3-0, 3-1 and 3-2 are wins; 2-3, 1-3 and 0-3 are losses. Gold rows are wins and red rows are losses. The number and percentage show the actual completed-match frequency. Compare 3-2 with 2-3 for pressure performance, and decisive wins with decisive losses to identify whether the overall game pattern is under control.'],ja:['接戦パフォーマンスの見方','各行はこの選手の視点で正規化されています。3-0、3-1、3-2は勝ち、2-3、1-3、0-3は負けです。金色は勝ち、赤色は負けを示します。数字と割合は完了試合での実際の頻度です。3-2と2-3を比べてプレッシャー下のパフォーマンスを確認し、大差の勝ちと大差の負けを比べて試合全体の主導権を握れているかを分析してください。']};
howToRead.rates = { en:['How to Read Win-Rate Charts','The monthly chart smooths short-term fluctuations and is best for checking whether results are changing across training blocks. The match-day chart is more sensitive to one session. Use the tooltip’s W/L total and opponent-category breakdown before drawing conclusions from a high or low percentage.'],ja:['勝率グラフの見方','月別グラフは短期的な変動をならし、練習期間ごとの変化を確認するのに向いています。試合日別グラフは1回の練習の影響を受けやすい表示です。高い・低い勝率だけで判断せず、ツールチップの勝敗数と対戦相手カテゴリ別の内訳を確認してください。']};
howToRead.sets = { en:['How to Read Set View','Gold bars are sets won and red bars are sets lost on each match day. The white line is that day’s net-set difference. Compare it with match results to distinguish narrow 3-2 losses from more decisive losses, then identify whether late-set execution or overall rally quality needs attention.'],ja:['セット推移の見方','金の棒は各試合日の獲得セット、赤の棒は失セットです。白線はその日のセット差を示します。試合結果と合わせて確認し、3-2の惜敗なのか、より大きな差の敗戦なのかを見分け、終盤の得点力かラリー全体の質かを振り返ってください。']};
howToRead.rank = { en:['How to Read Category Rank by Month','This is the player’s position only within their Player Category for each month. A medal marks a top-three rank. Monthly rank requires at least two completed matches on every recorded match day that month, so “Not eligible” means the participation threshold was not met, not that the player performed poorly. Compare rank with match count and opponent mix before evaluating change.'],ja:['カテゴリ内月間順位の見方','これは各月における同じ選手カテゴリ内での順位です。1位から3位にはメダルが表示されます。月間順位の対象には、その月のすべての試合日に完了試合を2試合以上行う必要があります。「対象外」は参加条件を満たしていないことを示すもので、成績の良し悪しを示すものではありません。試合数と対戦相手の構成も合わせて変化を確認してください。']};
document.addEventListener('click', event => { const button = event.target.closest('.how-to-read'); if (!button) return; const helpKey = button.closest('.win-rate-trends') ? 'rates' : button.closest('.rank-timeline') ? 'rank' : button.dataset.help, content = howToRead[helpKey]?.[language] || howToRead[helpKey]?.en; if (!content) return; const parentDialog = button.closest('dialog'); if (parentDialog && parentDialog.id !== 'how-to-read-dialog') { let panel = parentDialog.querySelector('.inline-how-to-read'), exists = Boolean(panel); if (!panel) { panel = document.createElement('section'); panel.className = 'inline-how-to-read'; parentDialog.querySelector('[id$="-content"]').append(panel); } panel.innerHTML = `<b>${content[0]}</b><p>${content[1]}</p>`; panel.hidden = exists ? !panel.hidden : false; return; } document.querySelector('#how-to-read-content').innerHTML = `<p class="eyebrow">HOW TO READ</p><h2>${content[0]}</h2><p>${content[1]}</p>`; document.querySelector('#how-to-read-dialog').showModal(); });
fetch('./public-data.json').then(response => response.ok ? response.json() : Promise.reject()).catch(() => fetch(API_URL).then(response => response.json())).then(result => { data=result; player=data.players.find(item => item.playerId === playerId); if (!player) throw Error(); matches=data.matches.filter(match => (match.player1Id===playerId || match.player2Id===playerId) && eventType(match)==='Training').sort((a,b)=>b.matchDate.localeCompare(a.matchDate)); supplementEntries = data.players.map(item => ({ kanjiName:item.displayName, romanizedName:item.englishName, playerCategory:item.schoolLevel, playingHand:item.playingHand, grip:item.grip, playingStyle:item.playingStyle, forehandType:item.forehandRubberType, forehandModel:item.forehandRubber, backhandType:item.backhandRubberType, backhandModel:item.backhandRubber })); document.title=`${player.displayName} | Little Kings`; render(); const selectedMatch = requestedOpponentId && matches.find(match => match.player1Id === requestedOpponentId || match.player2Id === requestedOpponentId); if (selectedMatch) openHeadToHead(selectedMatch.matchId); }).catch(() => document.querySelector('#profile-hero').innerHTML='<div class="loading">Unable to load this player profile.</div>');
document.querySelector('#language-toggle').onclick=()=>{language=language==='en'?'ja':'en';localStorage.setItem('lk-language',language);render();}; document.querySelector('#player-month-prev').onclick=()=>{statsMonthStart++;render();}; document.querySelector('#player-month-next').onclick=()=>{statsMonthStart--;render();}; document.querySelector('#player-overall-select').onchange=event=>{statsOverallPeriod=event.target.value;render();}; document.addEventListener('click',event=>{const nav=event.target.closest('.opponent-nav button');if(nav){if(nav.dataset.period==='month')monthlyIndex+=Number(nav.dataset.direction);else yearlyIndex+=Number(nav.dataset.direction);render();return}const card=event.target.closest('.match-card');if(card?.dataset.matchId)openHeadToHead(card.dataset.matchId);if(event.target.closest('.modal-close'))document.querySelectorAll('dialog[open]').forEach(dialog=>dialog.close());});
